pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 blockOffset, uint256 blockTimeOffset) public {
        // Bound: only 10 ether triggers the if condition
        vm.assume(amount == 10 ether);
        // Bound: block number must be >= 1 so we can set it
        vm.assume(blockOffset > 0);
        vm.roll(blockOffset);
        vm.warp(block.timestamp + blockTimeOffset + 1); // Ensure timestamp > pastBlockTime (reference)
        uint256 balanceBefore = address(c).balance;
        uint256 senderBalanceBefore = address(this).balance;
        // Fund the contract
        vm.deal(address(c), 100 ether);
        // Call fallback
        (bool success, ) = address(c).call{value: amount}("");
        require(success, "fallback failed");
        uint256 balanceAfter = address(c).balance;
        uint256 senderBalanceAfter = address(this).balance;
        // Rule: If block.number % 15 == 0, the contract transferred its full balance to the sender
        if (blockOffset % 15 == 0) {
            // Contract sends its entire balance, so final balance should be amount (new incoming) if no other funds? Actually contract had 100 ether + amount, then sends all balance before update? Let's derive:
            // Before call: contract has 100 ether. After receiving amount, it has 100 + amount. Then if block%15==0, it sends address(this).balance (which is the whole contract balance after receiving). So final balance = 0.
            assertTrue(balanceAfter == 0, "Contract should have zero balance after transfer");
            // Sender gets the contract's entire balance at the time of transfer (100 ether + amount)
            assertTrue(senderBalanceAfter - senderBalanceBefore == 100 ether + amount, "Sender should receive full contract balance");
        } else {
            // No transfer: contract balance increases by amount
            assertTrue(balanceAfter == balanceBefore + amount, "Contract balance should increase by amount");
            // Sender balance decreases by amount
            assertTrue(senderBalanceAfter == senderBalanceBefore - amount, "Sender balance should decrease by amount");
        }
    }
}

