pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 blockNumber, uint256 timestamp, uint256 blockNumber2, uint256 timestamp2) public {
        // Bound parameters to reasonable values
        timestamp = bound(timestamp, 1, 2**40);
        blockNumber = bound(blockNumber, 1, 2**40);
        timestamp2 = bound(timestamp2, timestamp + 1, timestamp + 1000);
        blockNumber2 = bound(blockNumber2, blockNumber + 1, blockNumber + 100);

        // Set block parameters for first call
        vm.roll(blockNumber);
        vm.warp(timestamp);

        // Fund the contract with initial balance
        vm.deal(address(c), 20 ether);

        // Make first fallback call that should pass (require timestamp > pastBlockTime)
        // and set pastBlockTime
        vm.deal(address(this), 10 ether);
        (bool success1, ) = address(c).call{value: 10 ether}("");

        // Record balance before second call
        uint256 balanceBefore = address(c).balance;

        // Advance time and block for second call
        vm.roll(blockNumber2);
        vm.warp(timestamp2);

        // Make second fallback call
        vm.deal(address(this), 10 ether);
        (bool success2, ) = address(c).call{value: 10 ether}("");

        uint256 balanceAfter = address(c).balance;

        // The rule: if second call succeeded, the balance difference must be at least 10 ether
        // (because the call either transferred out 10 ether if block%10==0, or just kept the 10 ether)
        // In the buggy version, transfer happens at block%10==0 instead of block%15==0
        // causing balance to change by 10 ether more often
        // But the key invariant: when block%10==0, balance must decrease by 10 ether
        // For the reference, when block%10==0 but block%15!=0, balance increases by 10 ether (no transfer)
        // So we check: if block%10 == 0, the balance difference cannot be exactly 10 ether (increase)
        if (success2 && blockNumber2 % 10 == 0) {
            // In the reference, balanceAfter = balanceBefore + 10 ether (no transfer)
            // In the mutant, balanceAfter = balanceBefore - 10 ether (transfer) so difference is -10 ether
            // We assert that the difference is NOT exactly +10 ether (which would mean no transfer happened)
            assertTrue(balanceAfter != balanceBefore + 10 ether, "Bug: balance increased by 10 ether when it should have decreased");
        } else {
            // Otherwise always true
            assertTrue(true);
        }
    }
}

