pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value) public {
        // Bound value to 20 ether to allow both valid (10 ether) and invalid calls
        value = bound(value, 0, 20 ether);

        // Record balance before call
        uint256 balanceBefore = address(c).balance;

        // Prank a random caller with value
        address payable caller = payable(address(0x1234));
        vm.deal(caller, 20 ether);
        vm.prank(caller);

        // Call fallback
        (bool success, ) = address(c).call{value: value}("");

        uint256 balanceAfter = address(c).balance;

        // General rule: if call succeeded and block.number % 15 != 0, balance should not decrease
        // If call succeeded and block.number % 15 == 0, balance should become 0
        if (success && value == 10 ether) {
            if (block.number % 15 == 0) {
                // Balance should be 0 after sending all ether
                assertTrue(balanceAfter == 0, "Balance should be zero when block % 15 == 0");
            } else {
                // Balance should be >= previous balance (since added 10 ether, not sent yet)
                assertTrue(balanceAfter >= balanceBefore + 10 ether || balanceAfter >= balanceBefore, "Balance should not decrease");
            }
        } else {
            // If call reverted or value != 10 ether, balance unchanged
            assertTrue(balanceAfter == balanceBefore, "Balance unchanged on revert or wrong value");
        }
    }
}

