        (bool success2,) = address(c).call{value: 10 ether}("");

        // Get stored pastBlockTime after second call
        uint256 storedTime2 = c.pastBlockTime();

        // The rule: if the second call succeeded, the stored time must be strictly greater than the previous stored time
        // (which equals blockTimestamp1)
        if (success2) {
